import { Component, inject } from '@angular/core';
import { NZ_MODAL_DATA } from 'ng-zorro-antd/modal';
import { Diet } from 'src/app/diet-grid/diet.model';
import { NewsSource } from 'src/app/news-source/news-source.model';
import { NewsSourcesService } from 'src/app/services/news-sources.service';

@Component({
  selector: 'today',
  templateUrl: './today.component.html',
  styleUrl: './today.component.scss',
})
export class TodayComponent {
  readonly nzModalData = inject(NZ_MODAL_DATA);
  diet: Diet;

  newsSource1: NewsSource;
  newsSource2: NewsSource;

  constructor(private newsSourcesSvc: NewsSourcesService) {}

  ngOnInit() {
    const currentDay = new Date().getDay();

    this.diet = this.nzModalData.diet;
    const newsSourceId1 = this.diet.dietDays[currentDay].newsSourceIds[0];
    const newsSourceId2 = this.diet.dietDays[currentDay].newsSourceIds[1];

    this.newsSourcesSvc.fetchNewsSource(newsSourceId1).subscribe((newsSource) => {
      this.newsSource1 = newsSource;
    });
    this.newsSourcesSvc.fetchNewsSource(newsSourceId2).subscribe((newsSource) => {
      this.newsSource2 = newsSource;
    });
  }
}
