import { Injectable } from '@angular/core';
import { AngularFirestore } from '@angular/fire/compat/firestore';
import { map, Observable } from 'rxjs';
import { NewsSource } from '../news-source/news-source.model';

@Injectable({
  providedIn: 'root',
})
export class NewsSourcesService {
  constructor(private fire: AngularFirestore) {}

  fetchNewsSource(id: string): Observable<NewsSource> {
    return this.fire
      .doc('/newsSources/' + id)
      .snapshotChanges()
      .pipe(
        map((newsSourceData) => {
          // console.log('[FIREBASE]Got news source:', newsSourceData);
          return newsSourceData.payload.data() as NewsSource;
        })
      );
  }
}
